  test(world, actor, ctx) {
    if (!world.has(actor, Player)) return false;
    if (ctx.target > 0) return false;
    const tileType = getTile(ctx.nx, ctx.ny);
    const eq = world.get(actor, Equipment);
    const weaponId = eq?.weapon || 0;

