function processPressurePlinths(world) {
  for (const [id, pos, link, inter] of world.query(Position, HydraulicsLink, Interactable)) {
    if (String(link?.role || "") !== "plinth") continue;
    const threshold = Math.max(1, Number(inter?.params?.thresholdWeight || 25) | 0);
    const total = tileWeight(world, pos.x, pos.y, id);
    const pressed = total >= threshold;
    const nextState = pressed ? "pressed" : "unpressed";
    const prevState = String(world.get(id, ObjectState)?.state || "unpressed");
    if (prevState === nextState) continue;
    world.set(id, ObjectState, { state: nextState });
    const changed = setLinkedPortcullisState(world, String(link?.linkId || ""), pressed, "pressure_plinth");
    world.emit("hydraulics:plinth", {
      plinthId: id | 0,
      linkId: String(link?.linkId || ""),
      pressed,
      thresholdWeight: threshold,
      totalWeight: total,
      gatesChanged: changed,
      at: { x: pos.x | 0, y: pos.y | 0 },
    });
  }
}

function pushGasHazards(world, x, y, dx, dy) {
  const fromX = x | 0;
  const fromY = y | 0;
  const toX = fromX + (dx | 0);
  const toY = fromY + (dy | 0);
  if (!isWalkable(toX, toY) || isSolidBlockedAt(world, toX, toY)) return 0;
  let moved = 0;
  for (const id of entitiesAtPoint(world, fromX, fromY)) {
    const hazard = world.get(id, HazardArea);
    if (!hazard) continue;
    const kind = String(hazard.kind || "").toLowerCase();
    if (kind !== "gas" && kind !== "steam") continue;
    world.set(id, Position, { x: toX, y: toY });
    moved++;
  }
  return moved;
}

function processSteamVents(world) {
  const step = Number(world.step || 0) | 0;
  for (const [id, pos, ident, inter] of world.query(Position, NamedIdentity, Interactable)) {
    if (String(ident?.identity || "") !== "steam_vent") continue;
    if (String(inter?.action || "") !== "inspectSteamVent") continue;
    const params = (inter?.params && typeof inter.params === "object") ? inter.params : {};
    const periodTurns = Math.max(1, Number(params.periodTurns || 6) | 0);
    const activeTurns = Math.max(1, Math.min(periodTurns, Number(params.activeTurns || 2) | 0));
    const range = Math.max(1, Number(params.range || 4) | 0);
    let dx = Math.sign(Number(params.dirX || 0) | 0);
    let dy = Math.sign(Number(params.dirY || 0) | 0);
    if (dx === 0 && dy === 0) dy = 1;
    if (dx !== 0 && dy !== 0) dy = 0;
    const pushForce = Math.max(1, Number(params.pushForce || 1) | 0);
    const damage = Math.max(0, Number(params.damage || 2) | 0);
    const cycleTurn = step % periodTurns;
    const active = cycleTurn < activeTurns;
    if (world.has(id, ObjectState)) {
      world.set(id, ObjectState, { state: active ? "venting" : "idle" });
    }
    if (!active) continue;

    let pushedHazards = 0;
    for (let d = 1; d <= range; d++) {
      const tx = (pos.x | 0) + dx * d;
      const ty = (pos.y | 0) + dy * d;
      if (!isWalkable(tx, ty)) break;
      spawnHazard(world, {
        x: tx,
        y: ty,
        kind: "steam",
        medium: "air",
        turnsLeft: 1,
        radius: 0,
        tickDamage: damage,
        damageType: "steam",
        cause: "steam_vent",
        sourceId: id | 0,
        sourceKind: "steam_vent",
        identity: "steam_blast",
        name: "Steam Blast",
        meta: { source: "steam_vent", lineStep: d },
      });

// rules/systems/tileStepEffectSystem.js
// "moved" event listener that applies tile step-on effects:
//   - Shallow water extinguishes burn
//   - Lava scorches + applies burn
//   - Ice slides the actor in the same direction (instant chain)
//
// A Pushable entity on a tile suppresses the effect (statue bridge mechanic).

import { Position } from "../components/Position.js";
import { Vitality } from "../components/Vitality.js";
import { ActiveEffects } from "../components/ActiveEffects.js";
import { Pushable } from "../components/Pushable.js";
import { Flying } from "../components/Flying.js";
import { findTileStepEffect } from "../data/tileStepEffects.js";
import { TILE_ICE } from "../environment/dungeon/constants.js";
import { getTile, isWalkable } from "../environment/dungeon/tileMap.js";
import { dealDamage } from "../utils/dealDamage.js";
import { upsertTimedEffect } from "../utils/effectSemantics.js";
import { ensureActiveEffects } from "../utils/effects.js";
import { getTileQuerySnapshot } from "../utils/tileQueryCache.js";
import { statusStrength } from "../utils/statusFacade.js";

const INSTALLED = Symbol.for("jshack:tileStepEffect:installed");
const MAX_SLIDE = 50;

// Re-entry guard: entities currently mid-slide don't trigger another slide
const _sliding = new Set();

/**
 * Install the tile step effect listener. Call once per world in configureWorld().
 * @param {import('../../lib/ecs-js/index.js').World} world
 */
export function installTileStepEffectListener(world) {
  if (!world || world[INSTALLED]) return;
  world[INSTALLED] = true;

  world.on("moved", ({ id, from, to }) => {
    try {
      _handleStep(world, id, from, to);
    } catch (e) {
      console.debug("[tileStepEffect] handler failed:", e);
    }
  });
}

/**
 * @param {any} world
 * @param {number} id
 * @param {{ x: number, y: number }} from
 * @param {{ x: number, y: number }} to
 */
function _handleStep(world, id, from, to) {
  const tileType = getTile(to.x, to.y);
  const effect = findTileStepEffect(tileType);
  if (!effect) return;

  // Bridge check: a Pushable entity on the tile suppresses the effect
  if (_hasPushableAt(world, to.x, to.y, id)) return;

  // Only living entities are affected
  const vit = world.get(id, Vitality);
  if (!vit || (vit.hp | 0) <= 0) return;
  if (statusStrength(world, id, "stasis") > 0) return;
  if (world.has(id, Flying)) return;

  switch (effect.type) {
    case "extinguish":
      _extinguish(world, id, effect);
      break;
    case "scorch":
      _scorch(world, id, effect);
      break;
    case "slide":
      // Re-entry guard: mid-slide "moved" events apply non-slide effects
      // (e.g. scorch when sliding off ice onto lava) but don't nest slides
      if (_sliding.has(id)) return;
      _slide(world, id, from, to, effect);
      break;
  }
}

/** Check if any Pushable entity (other than `exclude`) occupies (x, y). */
function _hasPushableAt(world, x, y, exclude) {
  // Query live Position data rather than the per-tick snapshot cache,
  // because a statue pushed mid-tick won't appear in the stale cache.
  for (const [id, pos] of world.query(Position)) {
    if (id !== exclude && pos.x === x && pos.y === y && world.has(id, Pushable)) return true;
  }
  return false;
}

/** Shallow water: remove burn effects. */
function _extinguish(world, id, effect) {
  const ae = /** @type {any} */ (world.get(id, ActiveEffects));
  if (!ae || !Array.isArray(ae.effects)) return;
  const before = ae.effects.length;
  ae.effects = ae.effects.filter(e => e.key !== "burn");
  if (ae.effects.length < before) {
    world.emit("tile:waded", { actor: id });
  }
}

/** Lava: deal fire damage + apply burn status. */
function _scorch(world, id, effect) {
  const result = dealDamage(world, {
    target: id,
    amount: effect.damage || 3,
    type: effect.damageType || "fire",
    cause: "lava",
  });

  // Apply burn to survivors
  if (result.applied && !result.killed && effect.status) {
