  constructor(world, frame) {
    this.world = world;
    this._frame = frame;
    this._cancelled = false;
    this._cancelReason = null;
    this._handled = false;
  }

  get actor() { return this._frame.actor | 0; }
  get target() { return this._frame.target | 0; }

  get actorPos() {
    const pos = this.world.get(this.actor, Position);
