 * @param {World} world
 * @param {number} actor
 * @param {any} intent
 */
function readTargetPoint(world, actor, intent) {
  const byPoint = readIntentPoint(intent);
  if (byPoint) return byPoint;

  const targetId = Number(intent?.targetId || 0) | 0;
  if (targetId > 0) {
