export function applyDrainLifeDamageInterrupt(world, { target, source, amount, cause }) {
  const actor = Number(target || 0) | 0;
  if (!(actor > 0)) return false;

  const ch = world.get(actor, Channeling);
  if (!ch || String(ch.spellId || "") !== "drain_life") return false;

  try { world.remove(actor, Channeling); } catch {}

  const ae = world.get(actor, ActiveEffects);
  if (ae && Array.isArray(ae.effects)) {
    ae.effects = ae.effects.filter((e) => String(e?.key || "").toLowerCase() !== "drain_life_channel");
  }

  world.emit("spell:drain_life:break", {
    actor,
    targetId: Number(source || 0) | 0,
    spellId: "drain_life",
    reason: "damage_interrupt",
    amount: Number(amount || 0) | 0,
    cause: String(cause || ""),
  });

  world.emit("channeling:cancelled", {
    actor,
    spellId: "drain_life",
    reason: "damage_interrupt",
  });

  return true;
}

/** @param {import('../../lib/ecs-js/index.js').World} world */
export function channelingSystem(world) {
  let _isBlocked = null; // lazily built for breakOnNoLos checks
  for (const [id, ch] of world.query(Channeling)) {
    // Dead actors lose their channel
    const vit = world.get(id, Vitality);
    if (vit && (vit.hp | 0) <= 0) {
      try { world.remove(id, Channeling); } catch {}
      world.emit('channeling:cancelled', { actor: id, spellId: ch.spellId, reason: 'dead' });
      continue;
    }

    const interruption = getChannelInterruptionReason(world, id);
    if (interruption) {
      try { world.remove(id, Channeling); } catch {}
      world.emit('channeling:cancelled', {
        actor: id,
        spellId: ch.spellId,
        reason: interruption,
      });
      continue;
    }

    // breakOnMove: cancel if caster left anchor position
    if (ch.breakOnMove && ch.anchorX != null && ch.anchorY != null) {
      const cPos = world.get(id, Position);
      if (cPos && ((cPos.x | 0) !== (ch.anchorX | 0) || (cPos.y | 0) !== (ch.anchorY | 0))) {
        try { world.remove(id, Channeling); } catch {}
        world.emit('channeling:cancelled', {
          actor: id,
          spellId: ch.spellId,
          reason: 'caster_moved',
        });
        continue;
      }
    }

    // breakOnNoLos: cancel if caster no longer has LOS to target
    if (ch.breakOnNoLos && ch.targetId) {
      const cPos = world.get(id, Position);
      const tPos = world.get(ch.targetId, Position);
      if (cPos && tPos) {
        if (!_isBlocked) _isBlocked = blockedCallback(buildBlocksVisionMap(world));
        if (!hasLOS(cPos.x | 0, cPos.y | 0, tPos.x | 0, tPos.y | 0, _isBlocked)) {
          try { world.remove(id, Channeling); } catch {}
          world.emit('channeling:cancelled', {
            actor: id,
            spellId: ch.spellId,
            reason: 'los_break',
          });
          continue;
        }
      }
    }

    if (String(ch.mode || "cast") === "sustain") {
      const spell = getSpell(String(ch.spellId || ""));
      if (!spell) {
        try { world.remove(id, Channeling); } catch {}
        world.emit("channeling:cancelled", { actor: id, spellId: ch.spellId, reason: "invalid_spell" });
        continue;
      }

      const resource = spellCostResource(spell);
      const mana = world.get(id, Mana);
      const stamina = world.get(id, Stamina);
      const stamina = world.get(id, Stamina);
      const vitality = world.get(id, Vitality);
      const perTick = Math.max(0, Number(
        resource === "stamina"
          ? (ch.staminaPerTick ?? spellCostPerTick(spell))
          : resource === "life"
            ? (ch.lifePerTick ?? spellCostPerTick(spell))
            : (ch.manaPerTick ?? spellCostPerTick(spell))
      ));
      const have = Number(
        resource === "stamina"
          ? (stamina?.stamina ?? 0)
          : resource === "life"
            ? (vitality?.hp ?? 0)
            : (mana?.mana ?? 0)
      );
      const minLife = resource === "life" ? 1 : 0;
      if (have - perTick < minLife) {
        try { world.remove(id, Channeling); } catch {}
        world.emit("spell:oom", {
          actor: id,
          spellId: spell.id,
          need: perTick + minLife,
          have,
          costKind: resource === "stamina" ? "stamina" : resource === "life" ? "life" : "mana",
        });
        world.emit("channeling:cancelled", { actor: id, spellId: spell.id, reason: "oom" });
        continue;
      }

      if (resource === "stamina" && stamina) {
        stamina.stamina = have - perTick;
        stamina.regenCooldown = STAMINA_REGEN_COOLDOWN;
      } else if (resource === "life" && vitality) {
        vitality.hp = Math.max(1, have - perTick);
      } else if (mana) {
        mana.mana = have - perTick;
        mana.regenCooldown = MANA_REGEN_COOLDOWN;
      }

      try {
        runSpellScript(world, id, spell, {
          targetId: ch.targetId || id,
          x: ch.x,
          y: ch.y,
          _fromChanneling: true,
          _channelTick: true,
        });
      } catch {}

      world.emit("channeling:tick", {
        actor: id,
        spellId: spell.id,
        mode: "sustain",
        manaPerTick: resource === "mana" ? perTick : 0,
        staminaPerTick: resource === "stamina" ? perTick : 0,
        lifePerTick: resource === "life" ? perTick : 0,
        manaRemaining: Number(mana?.mana ?? 0),
        manaMax: effectiveMaxMana(world, id, mana),
        staminaRemaining: Number(stamina?.stamina ?? 0),
        staminaMax: effectiveMaxStamina(world, id, stamina),
        lifeRemaining: Number(vitality?.hp ?? 0),
      });
      continue;
    }

    ch.turnsRemaining -= 1;

    if (ch.turnsRemaining <= 0) {
      const itemAction = getUseAction(ch.itemActionId || "");
      if (itemAction) {
        try { world.remove(id, Channeling); } catch {}
        itemAction.onComplete(world, id, ch);
        world.emit('channeling:complete', { actor: id, spellId: ch.spellId || ch.itemActionId, mode: 'item_use' });
        continue;
      }

      // Channel complete — inject CastSpellIntent for castSpellSystem
      const castData = {
        spellId: ch.spellId,
        targetId: ch.targetId || id,
        _fromChanneling: true,
      };
      if (ch.x != null) castData.x = ch.x;
      if (ch.y != null) castData.y = ch.y;

      try { world.remove(id, Channeling); } catch {}
      try { world.add(id, CastSpellIntent, castData); } catch {}
      world.emit('channeling:complete', { actor: id, spellId: ch.spellId });
    } else {
      // Still channeling — emit progress for UI
      world.emit('channeling:tick', {
        actor: id,
        spellId: ch.spellId,
        mode: 'cast',
        turnsRemaining: ch.turnsRemaining,
        turnsTotal: ch.turnsTotal,
      });
    }
  }
}

import { createGameRuntime } from "../src/main/runtime/gameRuntime.js";

function parseArgs(argv) {
  const out = {
    seed: 0xC0FFEE,
    classId: "outlaw",
    playerName: "Headless Hero",
    startDepth: 1,
    turns: 500,
    reportEvery: 100,
    playerWait: false,
    actionsFile: "",
    dungeonType: null,
  };

  for (let i = 0; i < argv.length; i++) {
    const raw = String(argv[i] || "");
    if (!raw.startsWith("--")) continue;
    const [k, inlineV] = raw.split("=", 2);
    const key = k.slice(2);
    const value = inlineV != null ? inlineV : (argv[i + 1] && !String(argv[i + 1]).startsWith("--") ? argv[++i] : "true");

    switch (key) {
      case "seed": out.seed = Number(value); break;
      case "class": out.classId = String(value); break;
      case "name": out.playerName = String(value); break;
      case "depth": out.startDepth = Number(value); break;
      case "turns": out.turns = Number(value); break;
      case "report-every": out.reportEvery = Number(value); break;
      case "player-wait": out.playerWait = String(value) !== "false"; break;
      case "actions-file": out.actionsFile = String(value); break;
      case "dungeon-type": out.dungeonType = String(value || "").trim() || null; break;
      default: break;
    }
  }

  out.turns = Math.max(1, Number.isFinite(out.turns) ? (out.turns | 0) : 500);
  out.reportEvery = Math.max(1, Number.isFinite(out.reportEvery) ? (out.reportEvery | 0) : 100);
  return out;
}

function percentile(values, p) {
  if (!values.length) return 0;
  const sorted = [...values].sort((a, b) => a - b);
  const idx = Math.min(sorted.length - 1, Math.max(0, Math.ceil((p / 100) * sorted.length) - 1));
  return sorted[idx];
}

function mean(values) {
  if (!values.length) return 0;
  let sum = 0;
  for (let i = 0; i < values.length; i++) sum += values[i];
  return sum / values.length;
}

function fmtMs(n) {
  return `${n.toFixed(3)}ms`;
}

async function loadActionSchedule(path) {
  if (!path) return new Map();
  const raw = await Deno.readTextFile(path);
  const parsed = JSON.parse(raw);
  if (!Array.isArray(parsed)) throw new Error("actions-file must be a JSON array");

  const byTurn = new Map();
  for (const row of parsed) {
    const at = Number(row?.at);
    const action = row?.action;
    if (!Number.isFinite(at) || !action || typeof action.type !== "string") continue;
    const turn = Math.max(1, at | 0);
    if (!byTurn.has(turn)) byTurn.set(turn, []);
    byTurn.get(turn).push(action);
  }
  return byTurn;
}

async function main() {
  const cfg = parseArgs(Deno.args);
  const actionSchedule = await loadActionSchedule(cfg.actionsFile);

  const runtime = await createGameRuntime({
    seed: cfg.seed,
    classId: cfg.classId,
    playerName: cfg.playerName,
    startDepth: cfg.startDepth,
    dungeonType: cfg.dungeonType,
  });

  const stepTimes = [];
  const viewTimes = [];

  console.log("headless runtime start");
  console.log(JSON.stringify({
    seed: cfg.seed >>> 0,
    classId: cfg.classId,
    playerName: cfg.playerName,
    depth: cfg.startDepth,
    turns: cfg.turns,
    reportEvery: cfg.reportEvery,
    playerWait: cfg.playerWait,
    actionsFile: cfg.actionsFile || null,
    dungeonType: cfg.dungeonType,
  }));

  for (let turn = 1; turn <= cfg.turns; turn++) {
    const scheduled = actionSchedule.get(turn) || [];

    const t0 = performance.now();
    if (scheduled.length > 0) {
      for (const action of scheduled) runtime.dispatch(action);
    } else if (cfg.playerWait) {
      runtime.dispatch({ type: "rules.wait", payload: {} });
    } else {
      runtime.tick(1);
    }
    const t1 = performance.now();
    stepTimes.push(t1 - t0);

    if (turn % cfg.reportEvery === 0 || turn === cfg.turns) {
      const v0 = performance.now();
      const view = runtime.view();
      const v1 = performance.now();
      const viewMs = v1 - v0;
      viewTimes.push(viewMs);

      const snap = runtime.snapshot();
      console.log(JSON.stringify({
        turn,
        simStepMs: Number((stepTimes[stepTimes.length - 1] || 0).toFixed(3)),
        viewMs: Number(viewMs.toFixed(3)),
        entitiesVisible: Array.isArray(view.entities) ? view.entities.length : 0,
        entitiesAlive: snap.entitiesAlive,
        depth: snap.depth,
        player: snap.player,
      }));
    }
  }

  const finalSnap = runtime.snapshot();
  console.log("headless runtime summary");
  console.log(JSON.stringify({
    turns: cfg.turns,
    stepAvgMs: Number(mean(stepTimes).toFixed(3)),
    stepP95Ms: Number(percentile(stepTimes, 95).toFixed(3)),
    stepMinMs: Number(Math.min(...stepTimes).toFixed(3)),
    stepMaxMs: Number(Math.max(...stepTimes).toFixed(3)),
    viewAvgMs: Number(mean(viewTimes).toFixed(3)),
    viewP95Ms: Number(percentile(viewTimes, 95).toFixed(3)),
    final: finalSnap,
  }));

  console.log(`step avg ${fmtMs(mean(stepTimes))} | p95 ${fmtMs(percentile(stepTimes, 95))}`);
}

main().catch((err) => {
  console.error("headless-runner failed:", err);
  Deno.exit(1);
});
