function loadFloorChunk() {
  clearAll();
  const tiles = new Uint8Array(CHUNK_SIZE * CHUNK_SIZE).fill(TILE_FLOOR);
  loadChunk(0, 0, tiles);
}

// ── basic movement ──────────────────────────────────────────────────

Deno.test("movementSystem: basic move updates position", () => {
  loadFloorChunk();
  try {
    const world = new World({ seed: 42 });
    const id = world.create();
    world.add(id, Position, { x: 5, y: 5 });
    world.add(id, MoveIntent, { dx: 1, dy: 0 });

    movementSystem(world);

    const pos = world.get(id, Position);
    assertEquals(pos.x, 6);
    assertEquals(pos.y, 5);
    assertEquals(world.has(id, MoveIntent), false, "intent consumed");
  } finally { clearAll(); }
});

Deno.test("movementSystem: stasis blocks a queued move without validation", () => {
  loadFloorChunk();
  try {
    const world = new World({ seed: 42 });
    const id = world.create();
    world.add(id, Position, { x: 5, y: 5 });
    world.add(id, Vitality, { hp: 10, maxHp: 10 });
    applyStatusEffect(world, id, { key: "stasis", turnsLeft: 8 });
    world.add(id, MoveIntent, { dx: 1, dy: 0 });
    const blocked = [];
    world.on("intent:blocked", (event) => blocked.push(event));

    movementSystem(world);

    assertEquals(world.get(id, Position), { x: 5, y: 5 });
    assertEquals(world.has(id, MoveIntent), false, "stasis should consume the blocked intent");
    assertEquals(blocked, [{ actor: id, reason: "stasis" }]);
  } finally { clearAll(); }
});

Deno.test("movementSystem: emits moved event", () => {
  loadFloorChunk();
  try {
    const world = new World({ seed: 42 });
    const id = world.create();
    world.add(id, Position, { x: 5, y: 5 });
    world.add(id, MoveIntent, { dx: 0, dy: 1 });

    let movedEvent = null;
    world.on("moved", (ev) => { movedEvent = ev; });

    movementSystem(world);

    assert(movedEvent, "moved event should fire");
    assertEquals(movedEvent.id, id);
    assertEquals(movedEvent.from.x, 5);
    assertEquals(movedEvent.from.y, 5);
    assertEquals(movedEvent.to.x, 5);
    assertEquals(movedEvent.to.y, 6);
  } finally { clearAll(); }
});

// ecs/extensions.js
// Runtime extension definitions and World appendage methods.

/**
 * Define a named runtime extension for a World.
 *
 * Extensions are runtime-only capabilities. They may register listeners,
 * adapters, diagnostics, or other world-local behavior, and may return a
 * synchronous cleanup function.
 * @param {string} name
 * @param {(world:any)=>(void|Function)} installer
 * @param {{ key?: any }} [options]
 * @returns {{ key:any, name:string, install:(world:any)=>(void|Function) }}
 */
export function defineExtension(name, installer, options = {}) {
  if (typeof name !== 'string' || !name) {
    throw new Error('defineExtension: name must be a non-empty string');
  }
  if (typeof installer !== 'function') {
    throw new Error('defineExtension: installer must be a function');
  }
  const key = Object.prototype.hasOwnProperty.call(options, 'key')
    ? options.key
    : Symbol(name);
  return Object.freeze({ key, name, install: installer });
}

export function isExtensionLike(extension) {
  return typeof extension === 'function' || !!(extension && typeof extension === 'object' && typeof extension.install === 'function');
}

