  }

  // Build profiled scheduler: measure per system and per phase using high-res timer
  /** @type {Array<'ai'|'intents'|'effects'|'scripts'|'cleanup'>} */
  const phases = ['ai', 'intents', 'effects', 'scripts', 'cleanup'];
  /** @type {Record<string, Function[]>} */
