    this.scheduler = fn;
    return this;
  }

  /** System registration pass-through (core does not know phase semantics).
   * @param {(world:World, dt:number)=>void} fn
   * @param {string} [phase='default']
   * @param {{ before?:Function[], after?:Function[] }} [opts]
   * @returns {this}
