/**
 * Return the first direct child with `Component`, or null.
 *
 * @param {import("../../lib/ecs-js/index.js").World} world
 * @param {number} parent
 * @param {import("../../lib/ecs-js/index.js").Component} Component
 * @returns {[number, object] | null}
