    if (!_pe) return;
    const px = _pe.pos.x | 0;
    const py = _pe.pos.y | 0;
    const range = Math.max(1, Number(enemySpellDef.range || 8));
    const enemies = scanVisibleEnemies(world, px, py, range, {
