    targeting.openEnemyTargeting({
      spellId: id,
      spellName: enemySpellDef.name,
      range,
      enemies,
    });
    return;
  }

  targeting.cancelAll();
  _sharedRulesDispatcher({ type: 'rules.castActiveSpell', payload: { spellId: id } });
});

