// rules/utils/effects.js
// Shared helper to ensure an entity has the ActiveEffects component.

import { attach } from "../../lib/ecs-js/hierarchy.js";
import { ActiveEffects } from "../components/ActiveEffects.js";
import { Duration } from "../components/Duration.js";
import { Source } from "../components/Source.js";
import { StatusEffectNode } from "../components/StatusEffectNode.js";
import { TimedEffectNode } from "../components/TimedEffectNode.js";
import { descendantsWith } from "./topology.js";

function normalizeEffectKey(value) {
  return String(value || "").trim().toLowerCase();
}

export function isInvulnerabilityEffectKey(value) {
  const key = normalizeEffectKey(value);
  return key === "invulnerable" || key === "invuln";
}

/**
 * Ensure `entityId` has an ActiveEffects component with an `effects` array.
 * If the component already exists it is returned as-is; otherwise it is added.
 *
 * @param {import('../../lib/ecs-js/index.js').World} world
 * @param {number} id  entity id
 * @returns {{ effects: Array<any> } | null}  the ActiveEffects component, or null on failure
 */
export function ensureActiveEffects(world, id) {
  let ae = world.get(id, ActiveEffects);
  if (ae && Array.isArray(ae.effects)) return ae;
  try { world.add(id, ActiveEffects, { effects: [] }); } catch { /* already exists */ }
  ae = world.get(id, ActiveEffects);
  return (ae && Array.isArray(ae.effects)) ? ae : null;
}

/**
 * Create a topology-backed status effect node under `actorId`.
 *
 * @param {import("../../lib/ecs-js/index.js").World} world
 * @param {number} actorId
 * @param {{
 *   key:string,
 *   turnsLeft:number,
 *   maxTurns?:number,
 *   startedAtTurn?:number,
 *   potency?:number,
 *   stacks?:number,
 *   sourceId?:number,
 *   sourceKind?:string,
 *   sourceKey?:string,
 *   onsetLeft?:number,
 * }} effect
 * @returns {number}
 */
export function applyStatusEffect(world, actorId, effect) {
  const id = Number(actorId || 0) | 0;
  const key = String(effect?.key || "").trim();
  const requestedTurns = effect?.turnsLeft;
  const turnsLeft = requestedTurns === Infinity
    ? Infinity
    : Number(requestedTurns ?? 0) | 0;
  if (!(id > 0)) throw new Error("applyStatusEffect: actorId must be a positive entity id");
  if (!key) throw new Error("applyStatusEffect: effect.key is required");
  if (!(turnsLeft >= 0)) throw new Error("applyStatusEffect: turnsLeft must be >= 0");

  const potency = Number.isFinite(effect?.potency) ? Number(effect.potency) : 1;
  const stacks = Number.isInteger(effect?.stacks) && effect.stacks > 0 ? effect.stacks : 1;
  const normalizedKey = normalizeEffectKey(key);
  let nodeId = 0;

  for (const [candidateId, node] of descendantsWith(world, id, StatusEffectNode)) {
    if (normalizeEffectKey(node?.key) !== normalizedKey) continue;
    nodeId = candidateId;
    break;
  }

  if (!(nodeId > 0)) {
    nodeId = world.create();
    attach(world, nodeId, id);
  }

  const existingStatus = world.get(nodeId, StatusEffectNode);
  const existingDuration = world.get(nodeId, Duration);
  // Stasis is a deliberate one-way state transition. Keep it on the normal
  // status/timed topology, but give it an infinite Duration so it cannot
  // expire on a tick. A permanent status also cannot be downgraded later.
  const permanent = normalizedKey === "stasis"
    || existingDuration?.turnsLeft === Infinity;
  const nextStatus = {
    key,
    potency: Math.max(Number(existingStatus?.potency || 0), potency),
    stacks: existingStatus
      ? Math.max(1, Number(existingStatus.stacks || 0) | 0) + stacks
      : stacks,
  };
  if (existingStatus) world.set(nodeId, StatusEffectNode, nextStatus);
  else world.add(nodeId, StatusEffectNode, nextStatus);

  const nextDuration = {
    turnsLeft: permanent ? Infinity : turnsLeft,
    onsetLeft: Number(effect?.onsetLeft ?? 0) | 0,
    maxTurns: permanent ? Infinity : Number(effect?.maxTurns ?? turnsLeft) | 0,
    startedAtTurn: Number(effect?.startedAtTurn ?? 0) | 0,
  };
  if (existingDuration) {
    nextDuration.turnsLeft = existingDuration.turnsLeft === Infinity
      ? Infinity
      : Math.max(Number(existingDuration.turnsLeft || 0) | 0, nextDuration.turnsLeft);
    nextDuration.onsetLeft = Math.min(
      Math.max(0, Number(existingDuration.onsetLeft || 0) | 0),
      Math.max(0, nextDuration.onsetLeft),
    );
    nextDuration.maxTurns = existingDuration.maxTurns === Infinity
      ? Infinity
      : Math.max(Number(existingDuration.maxTurns || 0) | 0, nextDuration.maxTurns);
    nextDuration.startedAtTurn = Number.isFinite(existingDuration.startedAtTurn)
      ? (Number(existingDuration.startedAtTurn) | 0)
      : nextDuration.startedAtTurn;
  }

  if (world.has(nodeId, TimedEffectNode)) world.set(nodeId, TimedEffectNode, { key });
  else world.add(nodeId, TimedEffectNode, { key });

  if (existingDuration) world.set(nodeId, Duration, nextDuration);
  else world.add(nodeId, Duration, nextDuration);

  if (effect?.sourceId != null || effect?.sourceKind || effect?.sourceKey) {
    world.add(nodeId, Source, {
      kind: String(effect?.sourceKind || ""),
      id: Number(effect?.sourceId || 0) | 0,
      key: String(effect?.sourceKey || ""),
    });
  }

  return nodeId;
}

import { ActiveEffects } from "../components/ActiveEffects.js";
import { Beatitude } from "../components/Beatitude.js";
import { Duration } from "../components/Duration.js";
import { Equipment, NON_AMMO_GEAR_SLOTS } from "../components/Equipment.js";
import { SleepState } from "../components/SleepState.js";
import { Status } from "../components/Status.js";
import { StatusEffectNode } from "../components/StatusEffectNode.js";
import { TimedEffectNode } from "../components/TimedEffectNode.js";
import { EFFECT_DEFS } from "../data/effectDefs.js";
import { descendantsWith } from "./topology.js";

function normalizeKey(value) {
  return String(value || "").trim().toLowerCase();
}

export const STATUS_ALIASES = Object.freeze(new Map([
  ["asleep", "sleep"],
  ["sleeping", "sleep"],
]));

// Stasis is topology-only. Do not let an old ActiveEffects or Status write
// make it appear active again after its canonical migration.
const TOPOLOGY_ONLY_KEYS = new Set(["stasis"]);

export function canonicalStatusType(value) {
  const key = normalizeKey(value);
  return STATUS_ALIASES.get(key) || key;
}

function hasPositiveDuration(duration) {
  return duration === Infinity || (Number.isFinite(Number(duration)) && Number(duration) > 0);
}

function normalizeStrength(potency, stacks) {
  const p = Number.isFinite(potency) ? Number(potency) : 1;
  const s = Number.isInteger(stacks) && stacks > 0 ? stacks : 1;
  return Math.max(1, Math.round(Math.max(0, p) * s));
}

/**
 * @param {any} effect
 */
function isActiveEffect(effect) {
  if (!effect || typeof effect !== "object") return false;
  if ((Number(effect.onsetLeft || 0) | 0) > 0) return false;
  return hasPositiveDuration(effect.turnsLeft);
}

/**
 * Map effect keys -> projected semantic statuses.
 * Lower-cased on build.
 */
const EFFECT_KEY_TO_STATUSES = (() => {
  /** @type {Map<string, string[]>} */
  const out = new Map();
  for (let i = 0; i < EFFECT_DEFS.length; i++) {
    const def = EFFECT_DEFS[i];
    const keys = Array.isArray(def?.keys) ? def.keys : [];
    const statuses = Array.isArray(def?.statuses)
      ? def.statuses.map((s) => normalizeKey(s)).filter(Boolean)
      : [];
    if (statuses.length <= 0) continue;
    for (let k = 0; k < keys.length; k++) {
      const key = normalizeKey(keys[k]);
      if (!key || out.has(key)) continue;
      out.set(key, statuses);
    }
  }
  return out;
})();

function validEntity(world, entityId) {
  const id = Number(entityId || 0) | 0;
  if (!(id > 0)) return false;
  if (typeof world?.isAlive === "function") return !!world.isAlive(id);
  return true;
}

function readTopologyEffect(world, nodeId, effectNode, fallbackKey = "") {
  const key = normalizeKey(effectNode?.key || fallbackKey);
  if (!key) return null;

  const duration = world.get(nodeId, Duration);
  if (!duration) return null;
  if ((Number(duration?.onsetLeft || 0) | 0) > 0) return null;
  if (!hasPositiveDuration(duration?.turnsLeft)) return null;

  return {
    key,
    turnsLeft: duration.turnsLeft === Infinity ? Infinity : Number(duration.turnsLeft || 0) | 0,
    onsetLeft: Number(duration.onsetLeft || 0) | 0,
    potency: effectNode?.potency,
    stacks: effectNode?.stacks,
  };
}

function collectTopologyEffects(world, entityId) {
  const out = [];
  const seen = new Set();

  for (const [nodeId, effectNode] of descendantsWith(world, entityId, StatusEffectNode)) {
    const row = readTopologyEffect(world, nodeId, effectNode);
    if (!row) continue;
    out.push(row);
    seen.add(nodeId);
  }

  for (const [nodeId, timedNode] of descendantsWith(world, entityId, TimedEffectNode)) {
    if (seen.has(nodeId)) continue;
    const row = readTopologyEffect(world, nodeId, timedNode);
    if (!row) continue;
    out.push(row);
  }

  return out;
}

/**
 * Build a topology-aware status/effect snapshot for one entity.
 *
 * - Effects are read from runtime topology nodes first.
 * - Legacy ActiveEffects entries are included for migrated keys with no topology row.
 * - Statuses are projected from active effects via EFFECT_DEFS.
 * - If a status has no projected active-effect value, falls back to Status component.
 *
 * @param {{ get:(id:number, Comp:any)=>any, isAlive?:(id:number)=>boolean }} world
 * @param {number} entityId
 */
export function snapshotStatusState(world, entityId) {
  const id = Number(entityId || 0) | 0;
  if (!validEntity(world, id)) return null;

  /** @type {Map<string, number>} */
  const effectStrengths = new Map();
  /** @type {Map<string, number>} */
  const projectedStatusStrengths = new Map();

  const topologyEffects = collectTopologyEffects(world, id);
  const topologyKeys = new Set(topologyEffects.map((effect) => effect.key));

  const ae = world.get(id, ActiveEffects);
  const legacyEffects = Array.isArray(ae?.effects) ? ae.effects : [];
  const effects = topologyEffects.concat(
    legacyEffects.filter((effect) => {
      const key = normalizeKey(effect?.key);
